            <div class="flex items-start gap-2.5"><span :class="['grid h-10 w-10 shrink-0 place-items-center rounded-full text-xs font-bold', chat.color]">{{ chat.avatar }}</span><div class="min-w-0 flex-1"><div class="flex items-center justify-between gap-2"><span class="truncate text-xs font-bold text-slate-800">{{ chat.name }}</span><span class="shrink-0 text-[10px] text-slate-400">{{ chat.time }}</span></div><div class="mt-1 flex items-center justify-between gap-2"><span class="truncate text-[11px] text-slate-500">{{ chat.preview }}</span><span v-if="chat.unread" class="grid h-4 min-w-4 place-items-center rounded-full bg-blue-600 px-1 text-[9px] font-bold text-white">{{ chat.unread }}</span></div><div class="mt-2 flex items-center gap-1.5"><span class="rounded bg-slate-100 px-1.5 py-0.5 text-[9px] text-slate-500">{{ chat.status }}</span><span v-if="chat.priority==='High'" class="rounded bg-rose-50 px-1.5 py-0.5 text-[9px] font-semibold text-rose-600">High priority</span><span v-if="chat.waiting !== '—'" class="ml-auto text-[9px] text-amber-600">Waiting {{ chat.waiting }}</span></div></div></div>
          </button>
