        <div class="flex items-center justify-between border-b border-slate-100 bg-white px-5 py-2"><div class="flex items-center gap-2 text-[10px] text-slate-500"><span v-if="selected.viewers.length" class="flex items-center gap-1 rounded-full bg-amber-50 px-2 py-1 text-amber-700"><Eye class="h-3 w-3"/> {{ selected.viewers.join(', ') }} viewing</span><span v-else class="flex items-center gap-1"><ShieldCheck class="h-3 w-3 text-emerald-600"/> No other agent viewing</span><span class="hidden sm:inline">· First response target: 15 min</span></div><button @click="addNotePrompt" class="flex items-center gap-1 text-[10px] font-semibold text-blue-600"><StickyNote class="h-3.5 w-3.5"/> Add internal note</button></div>
