            <div v-else :class="['max-w-[78%] rounded-2xl px-4 py-3 shadow-sm', msg.direction==='out'?'rounded-br-md bg-blue-600 text-white':'rounded-bl-md border border-slate-200 bg-white text-slate-800']"><p class="whitespace-pre-wrap text-[13px] leading-5">{{ msg.text }}</p><div :class="['mt-1.5 flex items-center justify-end gap-1 text-[9px]',msg.direction==='out'?'text-blue-100':'text-slate-400']">{{ msg.time }} <span v-if="msg.direction==='out'">· {{ msg.status }}</span></div></div>
          </div>
        </div>
        <div class="border-t border-slate-200 bg-white p-4"><div v-if="selected.windowHours <= 0" class="mb-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[11px] text-amber-800">The 24-hour customer service window has expired. Use an approved template to continue.</div><div class="rounded-xl border border-slate-200 bg-slate-50 p-3 focus-within:border-blue-300 focus-within:bg-white"><textarea v-model="draft" :disabled="selected.windowHours <= 0 && !templateReady" rows="2" @keydown.ctrl.enter="sendMessage" @keydown.meta.enter="sendMessage" placeholder="Write a message... Type / for quick replies" class="w-full resize-none bg-transparent text-xs text-slate-800 outline-none placeholder:text-slate-400"></textarea><div class="mt-2 flex items-center justify-between"><div class="flex items-center gap-1"><button @click="showQuickReplies = !showQuickReplies" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" title="Quick replies"><Zap class="h-4 w-4"/></button><button @click="addAttachment" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" title="Attach file"><Paperclip class="h-4 w-4"/></button><input ref="attachmentInput" type="file" class="hidden" accept="image/*,video/*,audio/*,.pdf,.doc,.docx,.xlsx" @change="onAttachmentChange"/><button @click="showTemplate = !showTemplate" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" title="Templates"><FileText class="h-4 w-4"/></button><span class="ml-2 text-[10px] text-slate-400">Ctrl + Enter to send</span></div><button @click="sendMessage" :disabled="!draft.trim() || (selected.windowHours <= 0 && !templateReady)" class="flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-40">Send <Send class="h-3.5 w-3.5"/></button></div>
          <div v-if="showQuickReplies" class="mt-3 flex flex-wrap gap-2 border-t border-slate-100 pt-3"><button v-for="reply in quickReplies.filter(item => item.active)" :key="reply.shortcut" @click="insertQuickReply(reply)" class="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-[10px] text-slate-600 hover:border-blue-300">{{ reply.shortcut }} · {{ reply.label }}</button></div>
          <div v-if="showTemplate" class="mt-3 flex flex-wrap gap-2 border-t border-slate-100 pt-3"><button v-for="t in approvedTemplates" :key="t.id" @click="useTemplate(t)" class="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-[10px] text-slate-600 hover:border-blue-300">{{ t.name }} · {{ t.category }}</button></div>
        </div></div>
