      <section v-else class="grid flex-1 place-items-center text-sm text-slate-400">Select a conversation to start</section>
      <aside v-if="selected && showDetails" class="absolute bottom-0 right-0 top-[58px] z-30 w-[270px] overflow-y-auto border-l border-slate-200 bg-white p-4 shadow-xl xl:static xl:top-auto xl:z-auto xl:shrink-0 xl:shadow-none">
        <div class="flex items-center justify-between"><h3 class="text-xs font-bold text-slate-800">Customer details</h3><button @click="showDetails=false" class="rounded p-1 text-slate-400 hover:bg-slate-100"><X class="h-4 w-4"/></button></div>
        <div class="mt-5 text-center"><span :class="['mx-auto grid h-14 w-14 place-items-center rounded-full text-sm font-bold', selected.color]">{{ selected.avatar }}</span><h4 class="mt-2 text-sm font-bold">{{ selected.name }}</h4><p class="mt-1 text-[11px] text-slate-500">{{ selected.phone }}</p><p class="mt-1 text-[10px] text-slate-400">{{ selectedContact?.email }}</p><p class="mt-1 text-[10px] text-slate-400">{{ selectedContact?.company }} · {{ selectedContact?.firstContact }}</p><p class="mt-1 text-[10px] text-slate-400">{{ selectedContact?.notes }}</p></div>
        <div class="mt-5 border-t border-slate-100 pt-4"><div class="mb-2 flex items-center justify-between"><h4 class="text-[11px] font-bold text-slate-700">Tags</h4><button @click="addTag" class="text-[10px] font-semibold text-blue-600">+ Add</button></div><div class="flex flex-wrap gap-1.5"><span v-for="tag in selected.tags" :key="tag" class="rounded-full bg-blue-50 px-2 py-1 text-[9px] font-semibold text-blue-700">{{ tag }} <button @click="removeTag(tag)">×</button></span></div></div>
        <div class="mt-4 border-t border-slate-100 pt-4"><h4 class="text-[11px] font-bold text-slate-700">Quick actions</h4><button @click="createReminder" class="mt-2 flex w-full items-center gap-2 rounded-lg border border-slate-200 p-2.5 text-left text-[11px] font-medium text-slate-600 hover:bg-slate-50"><CalendarClock class="h-4 w-4 text-blue-600"/> Create follow-up reminder</button><button @click="selected.status='Resolved'" class="mt-2 flex w-full items-center gap-2 rounded-lg border border-slate-200 p-2.5 text-left text-[11px] font-medium text-slate-600 hover:bg-slate-50"><CheckCircle2 class="h-4 w-4 text-emerald-600"/> Mark as resolved</button></div>
        <div class="mt-4 border-t border-slate-100 pt-4"><div class="mb-2 flex items-center justify-between"><h4 class="text-[11px] font-bold text-slate-700">Follow-up reminders</h4><button @click="createReminder" class="text-[10px] font-semibold text-blue-600">+ Add</button></div><div v-if="followUps.length" class="space-y-2"><div v-for="reminder in followUps" :key="reminder.id" class="rounded-lg bg-amber-50 p-2 text-[10px] text-amber-900"><div class="flex items-center justify-between gap-2"><div class="font-semibold">{{reminder.when}}</div><button @click="completeReminder(reminder.id)" class="font-semibold text-emerald-700">Done</button></div><div class="mt-0.5">{{reminder.note}}</div></div></div><p v-else class="text-[10px] text-slate-400">No upcoming reminders.</p></div>
        <div class="mt-4 border-t border-slate-100 pt-4"><h4 class="text-[11px] font-bold text-slate-700">Internal notes</h4><textarea v-model="noteDraft" rows="2" placeholder="Add a private note..." class="mt-2 w-full rounded-lg border border-slate-200 p-2 text-[10px] outline-none focus:border-blue-300"></textarea><button @click="saveNote" class="mt-1 w-full rounded-lg bg-slate-900 py-2 text-[10px] font-semibold text-white">Save note</button></div>
        <div class="mt-4 border-t border-slate-100 pt-4"><h4 class="text-[11px] font-bold text-slate-700">Customer timeline</h4><div class="mt-3 space-y-3"><div v-for="event in timeline" :key="event" class="flex gap-2 text-[10px] text-slate-500"><span class="mt-1 h-1.5 w-1.5 shrink-0 rounded-full bg-blue-500"></span>{{ event }}</div></div></div>
      </aside>
    </div>
    <div v-if="showReminderModal" class="fixed inset-0 z-[70] grid place-items-center bg-slate-900/35 p-4" @click.self="showReminderModal=false"><form @submit.prevent="saveReminder" class="w-full max-w-md rounded-2xl bg-white p-5 shadow-2xl"><div class="flex items-center justify-between"><h3 class="text-sm font-bold">Create follow-up reminder</h3><button type="button" @click="showReminderModal=false"><X class="h-4 w-4 text-slate-400"/></button></div><p class="mt-1 text-[11px] text-slate-500">Reminder for {{selected?.name}}</p><div class="mt-4 grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold text-slate-600">Date<input v-model="reminderForm.date" type="date" required class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-2 text-xs"/></label><label class="text-[11px] font-semibold text-slate-600">Time<input v-model="reminderForm.time" type="time" required class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-2 text-xs"/></label><label class="col-span-2 text-[11px] font-semibold text-slate-600">Reminder note<textarea v-model="reminderForm.note" rows="3" required class="mt-1.5 w-full rounded-lg border border-slate-200 p-3 text-xs" placeholder="What should the agent follow up about?"/></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" @click="showReminderModal=false" class="rounded-lg border border-slate-200 px-4 py-2 text-xs">Cancel</button><button class="rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white">Save reminder</button></div></form></div>
    <div v-if="toast" class="fixed bottom-5 right-5 z-[80] rounded-xl bg-slate-900 px-4 py-3 text-xs font-medium text-white shadow-xl">{{ toast }}</div>
  </div>
</template>
<script setup lang="ts">
import { computed, reactive, ref, onMounted, watch } from 'vue'
import { Bell, Search, SlidersHorizontal, PanelRight, ChevronLeft, Eye, ShieldCheck, StickyNote, Send, Zap, Paperclip, FileText, X, CalendarClock, CheckCircle2 } from '@lucide/vue'
import { agents, contacts, conversations } from '~/data/mock'
import type { Conversation } from '~/types/whatsapp'
import { useQuickReplyData, useTemplateData } from '~/composables/useWhatsAppAssets'
definePageMeta({ layout: 'dashboard' })
useHead({ title: 'Inbox — SumashDesk' })
const conversationData = reactive(conversations)
const selectedNumber = ref('+880 1700-000000')
const attachmentInput = ref<HTMLInputElement | null>(null)
const tabs = ['All','Mine','Unassigned','Unread','Pending','Resolved','Saved']
const activeTab = ref('All'), search = ref(''), selectedId = ref(101), mobileChatOpen = ref(false), showDetails = ref(true), showFilters = ref(false), unrepliedOnly = ref(false), priorityFilter = ref('All'), statusFilter = ref('All')
const draft = ref(''), noteDraft = ref(''), showQuickReplies = ref(false), showTemplate = ref(false), templateReady = ref(false), toast = ref('')
const savedFilters = useState<string[]>('sumashdesk-saved-filters', () => ['High Priority','My Follow-ups'])
const followUps = useState<{id:number;when:string;note:string}[]>('sumashdesk-follow-ups', () => [{id:1,when:'Today · 3:00 PM',note:'Confirm product availability'}])
const showReminderModal=ref(false)
const reminderForm=reactive({date:'2026-11-05',time:'10:00',note:'Follow up with customer'})
const quickReplies = useQuickReplyData()
const templates = useTemplateData()
const approvedTemplates = computed(() => templates.value.filter(t => t.status === 'Approved'))
const selected = computed(() => conversationData.find(c => c.id === selectedId.value) as Conversation | undefined)
const selectedContact = computed(() => contacts.find(c => c.id === selected.value?.contactId))
const filteredConversations = computed(() => conversationData.filter(c => {
 const q = search.value.toLowerCase(); const matches = !q || [c.name,c.phone,c.preview,...c.messages.map(m=>m.text)].join(' ').toLowerCase().includes(q)
 const tab = activeTab.value === 'All' || activeTab.value === 'Saved' || (activeTab.value === 'Mine' && c.assigned === 1) || (activeTab.value === 'Unassigned' && c.assigned === null) || (activeTab.value === 'Unread' && c.unread > 0) || (activeTab.value === 'Pending' && c.status === 'Pending') || (activeTab.value === 'Resolved' && c.status === 'Resolved')
 return matches && tab && (!unrepliedOnly.value || c.waiting !== '—') && (priorityFilter.value === 'All' || c.priority === priorityFilter.value) && (statusFilter.value === 'All' || c.status === statusFilter.value)
}))
const timeline = computed(() => { const chat=selected.value; if(!chat)return []; return [`First contact · ${selectedContact.value?.firstContact || 'Recently'}`, `Conversation opened · ${chat.time}`, `Priority set to ${chat.priority}`, `Status · ${chat.status}`, `Assigned to · ${agents.find(a=>a.id===chat.assigned)?.name || 'Unassigned'}`, ...chat.messages.slice(-4).map(m=>`${m.direction==='in'?'Customer message':m.direction==='note'?'Internal note':'Agent reply'} · ${m.time}`)] })
function notify(message:string){ toast.value=message; setTimeout(()=>toast.value='',2400) }

const csatSettings = ref({ enabled: true, afterResolve: true, once: true, mode: 'flow5' as 'flow5'|'quick3' })
function onConversationStatusChange(){
 const chat=selected.value
 if(!chat || chat.status!=='Resolved' || !csatSettings.value.enabled || !csatSettings.value.afterResolve) return
 try { const saved=localStorage.getItem('sumashdesk-csat-settings'); if(saved) csatSettings.value={...csatSettings.value,...JSON.parse(saved)} } catch {}
 if(!csatSettings.value.enabled || !csatSettings.value.afterResolve) return
 const key=`sumashdesk-csat-request-${chat.id}`
 if(csatSettings.value.once && localStorage.getItem(key)){notify('CSAT request was already sent for this conversation');return}
 const mode=csatSettings.value.mode || 'flow5'
 const body=mode==='flow5'
  ? 'Thank you for contacting Sumash Store. Please rate your support experience.'
  : 'Thank you for contacting Sumash Store. Please rate your support by selecting 1, 2 or 3.'
 chat.messages.push({id:Date.now(),text:mode==='flow5'?`${body} [WhatsApp Flow: Rate experience · 1–5 stars]`:`${body} [WhatsApp reply buttons: 1 · 2 · 3]`,direction:'out',time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),status:'Queued (demo)',author:'SumashDesk CSAT'})
 chat.preview='Customer satisfaction rating requested'
 localStorage.setItem(key,JSON.stringify({conversationId:chat.id,customer:chat.name,agent:agents.find(a=>a.id===chat.assigned)?.name||'Unassigned',mode,status:'queued-demo',createdAt:new Date().toISOString()}))
 notify(mode==='flow5'?'5-point WhatsApp Flow rating request queued (demo)':'3-button WhatsApp rating request queued (demo)')
}

function sendMessage(){ const chat=selected.value; if(!draft.value.trim() || !chat)return; if(chat.windowHours <= 0 && !templateReady.value){notify('Messaging window expired. Select an approved template.');return;} if(chat.viewers.length && !confirm(`${chat.viewers.join(', ')} is viewing this conversation. Send anyway?`))return; const text=draft.value.trim(); chat.messages.push({id:Date.now(),text,direction:'out',time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),status:'Sent',author:'Sadikul Islam'}); chat.preview=text; chat.time='now'; draft.value=''; templateReady.value=false; notify('Mock message sent') }
function insertQuickReply(reply:{id:number;text:string;usage:number}){draft.value=reply.text;reply.usage+=1;showQuickReplies.value=false}
function completeReminder(id:number){followUps.value=followUps.value.filter(item=>item.id!==id);notify('Follow-up marked completed')}
function saveNote(){ if(!noteDraft.value.trim() || !selected.value)return; selected.value.messages.push({id:Date.now(),text:noteDraft.value.trim(),direction:'note',time:'Just now',author:'Sadikul Islam'}); noteDraft.value=''; notify('Internal note added') }
function addNotePrompt(){ showDetails.value=true; notify('Add your note in the customer panel') }
function addTag(){ const tag=prompt('Enter a customer tag'); if(tag && selected.value && !selected.value.tags.includes(tag)) selected.value.tags.push(tag) }
function removeTag(tag:string){ if(selected.value) selected.value.tags=selected.value.tags.filter(t=>t!==tag) }
function createReminder(){reminderForm.date='2026-11-05';reminderForm.time='10:00';reminderForm.note=`Follow up with ${selected.value?.name||'customer'}`;showReminderModal.value=true}
function saveReminder(){const when=`${reminderForm.date} · ${reminderForm.time}`;followUps.value.unshift({id:Date.now(),when,note:reminderForm.note});showReminderModal.value=false;notify('Follow-up reminder saved')}
function saveCurrentFilter(){ const name=prompt('Name this filter'); if(name){savedFilters.value.push(name);notify('Filter saved')} }
function applySavedFilter(name:string){ activeTab.value='All'; priorityFilter.value=name==='High Priority'?'High':'All'; unrepliedOnly.value=name==='My Follow-ups'; notify(`Applied filter: ${name}`) }
function useTemplate(template:{name:string;body:string}){draft.value=template.body.replace(/\{\{1\}\}/g,selected.value?.name||'Customer');templateReady.value=true;showTemplate.value=false;notify(`Approved template ${template.name} inserted`)}
function addAttachment(){ attachmentInput.value?.click() }
function onAttachmentChange(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||!selected.value)return;const ext=file.name.split('.').pop()?.toLowerCase()||'';const kind=['png','jpg','jpeg','webp','gif'].includes(ext)?'image':['mp4','mov','webm'].includes(ext)?'video':['mp3','wav','ogg','m4a'].includes(ext)?'audio':'document';selected.value.messages.push({id:Date.now(),text:`${kind.toUpperCase()} attachment: ${file.name}`,direction:'out',time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),status:'Sent',author:'Sadikul Islam',kind});selected.value.preview=`Attachment: ${file.name}`;input.value='';notify('Mock attachment added to conversation')}
onMounted(()=>{try{const cfg=localStorage.getItem('sumashdesk-csat-settings');if(cfg)csatSettings.value={...csatSettings.value,...JSON.parse(cfg)}}catch{};const saved=localStorage.getItem('sumashdesk-demo-conversations');if(saved){try{const parsed=JSON.parse(saved);if(Array.isArray(parsed)&&parsed.length)conversationData.splice(0,conversationData.length,...parsed)}catch{localStorage.removeItem('sumashdesk-demo-conversations')}}})
watch(conversationData, value=>{if(import.meta.client)localStorage.setItem('sumashdesk-demo-conversations',JSON.stringify(value))},{deep:true})
watch(draft, value=>{if(value.startsWith('/'))showQuickReplies.value=true})
</script>
